CREATE TABLE knowledge_grants(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),snapshot_id uuid NOT NULL,recipient text NOT NULL,scope text NOT NULL CHECK(scope IN ('MAIN','CHILD')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,snapshot_id,recipient));
CREATE TABLE run_input_manifests(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),run_key text NOT NULL,agent_id text NOT NULL,revision integer NOT NULL,input_hash text NOT NULL,manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,run_key));
CREATE TABLE work_receipts(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),job_id uuid NOT NULL REFERENCES jobs(id),created_by text NOT NULL REFERENCES accounts(id),visibility text NOT NULL CHECK(visibility IN ('PRIVATE','REDACTED')),digest text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rehearsal_runs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),job_id uuid NOT NULL REFERENCES jobs(id),created_by text NOT NULL REFERENCES accounts(id),fingerprint text NOT NULL,rules_version text NOT NULL,scenario text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE benchmark_suites(id text PRIMARY KEY,version integer NOT NULL,data jsonb NOT NULL,digest text NOT NULL);
CREATE TABLE benchmark_runs(id uuid PRIMARY KEY,agent_id text NOT NULL,book text NOT NULL,owner_id text NOT NULL REFERENCES accounts(id),suite_id text NOT NULL REFERENCES benchmark_suites(id),fingerprint text NOT NULL,manifest jsonb NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
ALTER TABLE bids DROP CONSTRAINT bids_job_id_agent_id_key;
CREATE UNIQUE INDEX primary_bid_per_agent ON bids(job_id,agent_id) WHERE NOT(data ? 'counterofferOf');
CREATE TABLE negotiation_rounds(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),original_bid_id uuid NOT NULL REFERENCES bids(id),agent_id text NOT NULL,book text NOT NULL,client_id text NOT NULL REFERENCES accounts(id),requested_amount text NOT NULL,state text NOT NULL CHECK(state IN ('REJECTED','AWAITING_RECORD','RECORDED','EXPIRED')),reason text NOT NULL,terms_hash text NOT NULL,final_bid_id uuid UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,agent_id),FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
